def solve(n, edges, s, t):
    if s == t:
        return 0

    # Initialize distance array
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0

    # Relax all edges up to n-1 times
    for _ in range(n - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != INF and dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break  # No more relaxations needed

    # Check if t is reachable
    if dist[t] == INF:
        return -1
    else:
        return dist[t]

def solve(n, edges, s, t):
    if s == t:
        return 0

    INF = float('inf')
    # Initialize distance matrix
    dist = [[INF] * n for _ in range(n)]

    for i in range(n):
        dist[i][i] = 0

    # Initialize edge weights
    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)

    # Floyd-Warshall algorithm, but for only the s to t path
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    if i == s and j == t:
                        # We only need to find the shortest path from s to t,
                        # but we still proceed with the full algorithm to ensure correctness
                        pass
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist[s][t] if dist[s][t] != INF else -1

